/// A node in the parse tree. `data` is the rule name (or alias) that built it.
///
/// `Drop` and `Clone` are manual worklist implementations (#151, same as the
/// main crate's `Tree`): the derived glue recurses to tree depth, and a parse
/// result is as deep as the input is nested, so the derived glue overflows
/// small native stacks.
#[derive(Debug)]
pub struct Tree {
    pub data: String,
    pub children: Vec<Child>,
    pub meta: Meta,
}

impl Drop for Tree {
    fn drop(&mut self) {
        let is_tree = |c: &Child| matches!(c, Child::Tree(_));
        // Fast path: leaf-only children drop in place — no recursion possible.
        if !self.children.iter().any(is_tree) {
            return;
        }
        // Worklist of whole `children` vectors (3-word moves, never per-element
        // copies). Invariant: a vector is pushed only if it contains a subtree
        // with sub-subtrees; every `Tree` value therefore reaches its own
        // (recursive) drop with empty or leaf-only children, where the fast
        // path returns immediately — so native depth stays constant.
        let mut stack: Vec<Vec<Child>> = vec![std::mem::take(&mut self.children)];
        while let Some(mut vec) = stack.pop() {
            for child in vec.iter_mut() {
                if let Child::Tree(t) = child {
                    if t.children.iter().any(is_tree) {
                        stack.push(std::mem::take(&mut t.children));
                    }
                }
            }
            // `vec` drops here; every tree in it is now empty or leaf-only.
        }
    }
}

impl Clone for Tree {
    fn clone(&self) -> Self {
        // Explicit-frame deep copy: one heap frame per open node instead of one
        // native frame per tree level.
        struct Frame<'a> {
            src: std::slice::Iter<'a, Child>,
            data: String,
            meta: Meta,
            out: Vec<Child>,
        }
        fn frame(t: &Tree) -> Frame<'_> {
            Frame {
                src: t.children.iter(),
                data: t.data.clone(),
                meta: t.meta.clone(),
                out: Vec::with_capacity(t.children.len()),
            }
        }
        let mut stack = vec![frame(self)];
        loop {
            let top = stack
                .last_mut()
                .expect("clone stack never empties mid-walk");
            match top.src.next() {
                Some(Child::Tree(t)) => stack.push(frame(t)),
                Some(Child::Token(tok)) => top.out.push(Child::Token(tok.clone())),
                Some(Child::None) => top.out.push(Child::None),
                None => {
                    let done = stack.pop().expect("just peeked");
                    let tree = Tree {
                        data: done.data,
                        children: done.out,
                        meta: done.meta,
                    };
                    match stack.last_mut() {
                        Some(parent) => parent.out.push(Child::Tree(tree)),
                        None => return tree,
                    }
                }
            }
        }
    }
}

/// The result of a parse — usually a `Tree`, but a `?start` rule that collapses
/// via expand1 to a single token yields that bare `Token`, and a `?start` whose
/// sole alternative is an absent `[...]` placeholder collapses to a bare `None`
/// (Python's literal `None` result for `?start: [A]` on `""` with
/// `maybe_placeholders`, #289/#382). Mirrors the public API's `ParseTree::None`
/// (ADR-0033) so the bake stays byte-faithful to core.
#[derive(Clone, Debug)]
pub enum ParseTree {
    Tree(Tree),
    Token(Token),
    None,
}

enum NodeValue {
    Token(Token),
    Tree(Tree),
    Inline(Vec<Child>),
}

impl fmt::Display for Tree {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let children: Vec<String> = self
            .children
            .iter()
            .map(|c| match c {
                Child::Tree(t) => t.to_string(),
                Child::Token(tok) => format!("Token({}, {:?})", tok.type_, tok.value),
                Child::None => "None".to_string(),
            })
            .collect();
        write!(f, "Tree({}, [{}])", self.data, children.join(", "))
    }
}

impl fmt::Display for ParseTree {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseTree::Tree(t) => write!(f, "{}", t),
            ParseTree::Token(tok) => write!(f, "Token({}, {:?})", tok.type_, tok.value),
            ParseTree::None => write!(f, "None"),
        }
    }
}

// ───────────────────────────── lexer ─────────────────────────────

struct Scanner {
    re: Regex,
    /// (terminal id, capture-group index), in alternation order.
    groups: Vec<(u32, usize)>,
    /// Keyword retype per regex terminal: exact values hashed, `"..."i`
    /// keywords as anchored case-insensitive regexes (definition order).
    unless: HashMap<u32, (HashMap<String, u32>, Vec<(Regex, u32)>)>,
}

impl Scanner {
    fn new(data: &GrammarData) -> Scanner {
        let mut parts: Vec<String> = Vec::with_capacity(data.scan_groups.len());
        for (id, rx) in data.scan_groups {
            parts.push(format!("(?P<g{}>{})", id, rx));
        }
        let pattern = format!("{}{}", data.global_prefix, parts.join("|"));
        let re = Regex::new(&pattern).expect("baked scanner regex is valid");
        // Resolve each group's name to its capture index (a terminal pattern can
        // itself contain groups, so the index is not the alternation position).
        let name_to_idx: HashMap<String, usize> = re
            .capture_names()
            .enumerate()
            .filter_map(|(i, n)| n.map(|n| (n.to_string(), i)))
            .collect();
        let groups = data
            .scan_groups
            .iter()
            .map(|(id, _)| (*id, name_to_idx[&format!("g{}", id)]))
            .collect();
        let mut unless: HashMap<u32, (HashMap<String, u32>, Vec<(Regex, u32)>)> = HashMap::new();
        for (re_id, entries) in data.unless {
            let slot = unless.entry(*re_id).or_default();
            for (value, ci, kw_id) in *entries {
                if *ci {
                    let src = format!("^(?i:{})$", regex::escape(value));
                    let re = Regex::new(&src).expect("baked unless regex is valid");
                    slot.1.push((re, *kw_id));
                } else {
                    slot.0.entry(value.to_string()).or_insert(*kw_id);
                }
            }
        }
        Scanner { re, groups, unless }
    }

    /// Match a single token starting exactly at `pos`. `None` = nothing here.
    fn match_at<'t>(&self, text: &'t str, pos: usize) -> Option<(u32, &'t str)> {
        let caps = self.re.captures_at(text, pos)?;
        let m0 = caps.get(0)?;
        // Accept only a non-empty match beginning exactly at `pos`.
        if m0.start() != pos || m0.end() == pos {
            return None;
        }
        let value = m0.as_str();
        for (id, idx) in &self.groups {
            if caps.get(*idx).is_some() {
                let ty = self
                    .unless
                    .get(id)
                    .and_then(|(exact, ci)| {
                        exact.get(value).copied().or_else(|| {
                            ci.iter()
                                .find(|(re, _)| re.is_match(value))
                                .map(|(_, k)| *k)
                        })
                    })
                    .unwrap_or(*id);
                return Some((ty, value));
            }
        }
        None
    }
}

fn lex(data: &GrammarData, scanner: &Scanner, text: &str) -> Result<Vec<Token>, String> {
    let ignore: HashSet<u32> = data.ignore.iter().copied().collect();
    let mut tokens = Vec::new();
    // `pos` is the **byte** offset (drives regex slicing); `char_pos` is the
    // **character** index a token's `start_pos`/`end_pos` carry — Python parity,
    // the two diverge on non-ASCII input (#278). Both advance together.
    let mut pos = 0usize;
    let mut char_pos = 0usize;
    let mut line = 1usize;
    let mut col = 1usize;

    while pos < text.len() {
        match scanner.match_at(text, pos) {
            Some((id, value)) => {
                let start_line = line;
                let start_col = col;
                let start_pos = char_pos;
                for ch in value.chars() {
                    if ch == '\n' {
                        line += 1;
                        col = 1;
                    } else {
                        col += 1;
                    }
                    char_pos += 1;
                }
                pos += value.len();
                if !ignore.contains(&id) {
                    tokens.push(Token {
                        type_id: id,
                        type_: data.name_of(id).to_string(),
                        value: value.to_string(),
                        line: start_line,
                        column: start_col,
                        end_line: line,
                        end_column: col,
                        start_pos,
                        end_pos: char_pos,
                    });
                }
            }
            None => {
                let ch = text[pos..].chars().next().unwrap();
                return Err(format!(
                    "Unexpected character {:?} at line {}, column {}",
                    ch, line, col
                ));
            }
        }
    }

    // End-of-input sentinel (terminal id 0 = $END); carries the char index (#278).
    tokens.push(Token {
        type_id: 0,
        type_: data.name_of(0).to_string(),
        value: String::new(),
        line,
        column: col,
        end_line: line,
        end_column: col,
        start_pos: char_pos,
        end_pos: char_pos,
    });
    Ok(tokens)
}

